<h1 class="h3 mb-3">Contas a Receber</h1>
<table class="table tabela-dados"><thead><tr><th>ID</th><th>Cliente</th><th>Emissão</th><th>Vencimento</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($titulos as $t):?><tr><td><?=$t['id']?></td><td><?=$t['cliente_nome']?></td><td><?=date('d/m/Y',strtotime($t['data_emissao']))?></td><td><?=date('d/m/Y',strtotime($t['data_vencimento']))?></td><td>R$ <?=number_format((float)$t['valor'],2,',','.')?></td><td><?=$t['status']?></td><td><?php if($t['status']==='aberto'):?><a class="btn btn-sm btn-primary" href="<?=$config['app']['url_base']?>/contas-receber/baixar/<?=$t['id']?>">Baixar</a><?php else:?><a class="btn btn-sm btn-warning" href="<?=$config['app']['url_base']?>/contas-receber/reabrir/<?=$t['id']?>">Reabrir</a><?php endif;?></td></tr><?php endforeach;?></tbody></table>
